/**
 * Minimal single-page PDF with Helvetica text lines (no external PDF deps).
 */
export function buildSimpleTextPdf(title: string, lines: string[]): Buffer {
  const contentLines = [
    'BT',
    '/F1 16 Tf',
    '50 780 Td',
    `(${escapePdfText(title)}) Tj`,
    '/F1 11 Tf',
    '0 -28 Td',
  ];

  for (const line of lines) {
    contentLines.push(`(${escapePdfText(line)}) Tj`);
    contentLines.push('0 -16 Td');
  }
  contentLines.push('ET');

  const stream = contentLines.join('\n');
  const objects: string[] = [];
  objects.push('1 0 obj<< /Type /Catalog /Pages 2 0 R >>endobj\n');
  objects.push('2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1 >>endobj\n');
  objects.push(
    '3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>endobj\n',
  );
  objects.push(
    `4 0 obj<< /Length ${Buffer.byteLength(stream, 'utf8')} >>stream\n${stream}\nendstream\nendobj\n`,
  );
  objects.push('5 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>endobj\n');

  let pdf = '%PDF-1.4\n';
  const offsets: number[] = [0];
  for (const obj of objects) {
    offsets.push(Buffer.byteLength(pdf, 'utf8'));
    pdf += obj;
  }
  const xrefStart = Buffer.byteLength(pdf, 'utf8');
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += '0000000000 65535 f \n';
  for (let i = 1; i < offsets.length; i += 1) {
    pdf += `${String(offsets[i]).padStart(10, '0')} 00000 n \n`;
  }
  pdf += `trailer<< /Size ${objects.length + 1} /Root 1 0 R >>\n`;
  pdf += `startxref\n${xrefStart}\n%%EOF\n`;
  return Buffer.from(pdf, 'utf8');
}

function escapePdfText(value: string): string {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)')
    .replace(/[^\x20-\x7E]/g, '?');
}

/** Best-effort extraction of common DigiLocker / UIDAI e-Aadhaar XML fields. */
export function parseEaadhaarXmlFields(xml: string): Record<string, string> {
  const fields: Record<string, string> = {};
  const pick = (keys: string[]) => {
    for (const key of keys) {
      const attr = new RegExp(`${key}\\s*=\\s*"([^"]*)"`, 'i').exec(xml);
      if (attr?.[1]) {
        fields[key] = attr[1];
        return;
      }
      const tag = new RegExp(`<[^>]*:?${key}[^>]*>([^<]*)</`, 'i').exec(xml);
      if (tag?.[1]?.trim()) {
        fields[key] = tag[1].trim();
      }
    }
  };

  pick(['name', 'n']);
  pick(['dob', 'dateOfBirth']);
  pick(['gender', 'g']);
  pick(['uid', 'uid']);
  pick(['co', 'careof', 'careOf']);
  pick(['house', 'loc', 'vtc', 'dist', 'state', 'pc', 'country']);

  // Compose address if Poi/Poa style attributes exist on one element.
  const poa = /<[^>]*Poa[^>]*\/>/i.exec(xml)?.[0] ?? /<[^>]*Poa[^>]*>/i.exec(xml)?.[0];
  if (poa) {
    const parts = ['house', 'street', 'loc', 'vtc', 'dist', 'state', 'pc']
      .map((k) => new RegExp(`${k}\\s*=\\s*"([^"]*)"`, 'i').exec(poa)?.[1])
      .filter((v): v is string => Boolean(v && v.trim()));
    if (parts.length > 0) {
      fields.address = parts.join(', ');
    }
  }

  return fields;
}

export function eaadhaarXmlToPdf(xml: string): Buffer {
  const fields = parseEaadhaarXmlFields(xml);
  const lines = [
    `Name: ${fields.name ?? fields.n ?? '—'}`,
    `Date of birth: ${fields.dob ?? fields.dateOfBirth ?? '—'}`,
    `Gender: ${fields.gender ?? fields.g ?? '—'}`,
    `Aadhaar (masked/uid): ${fields.uid ?? '—'}`,
    `Address: ${fields.address ?? fields.co ?? '—'}`,
    '',
    'Source: DigiLocker e-Aadhaar XML API',
    'This printout is generated by Smart Kiosk for local preview/print.',
  ];
  return buildSimpleTextPdf('e-Aadhaar (DigiLocker)', lines);
}

export const EAADHAAR_SYNTHETIC_URI = 'eaadhaar:xml';

export function looksLikeAadhaarDoc(doc: {
  name?: string;
  description?: string;
  doctype?: string;
  issuer?: string;
}): boolean {
  const hay = [doc.name, doc.description, doc.doctype, doc.issuer]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return /aadhaar|aadhar|adhar|uidai|eaadhaar/.test(hay);
}
